+using System.Text.Json;
+using System.Text.Json.Serialization;
+using System.Text.Json.Serialization.Metadata;
+
+// --- 1. GetTypeInfo<T>: strongly-typed metadata retrieval ---
+var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);
+
+JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
+Console.WriteLine($"GetTypeInfo<Person> returned type: {personInfo.Type.Name}");
+
+string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
+Console.WriteLine($"Serialized: {json}");
+
+// --- 2. TryGetTypeInfo<T>: probe without throwing ---
+
+// 2a. Type the default resolver CAN handle (Person)
+if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? found))
+{
+    Console.WriteLine($"TryGetTypeInfo<Person> succeeded — type: {found!.Type.Name}");
+}
+
+// 2b. Type a restricted resolver CANNOT handle (UnknownWidget)
+//     Use a source-gen context that only knows about Person.
+var restricted = new JsonSerializerOptions { TypeInfoResolver = DemoContext.Default };
+
+if (restricted.TryGetTypeInfo<UnknownWidget>(out JsonTypeInfo<UnknownWidget>? missing))
+{
+    Console.WriteLine($"Resolved: {missing!.Type.Name}");
+}
+else
+{
+    Console.WriteLine("TryGetTypeInfo<UnknownWidget> returned false — no exception thrown");
+}
+
+// --- Types ---
+public record Person(string Name, int Age);
+public class UnknownWidget { public int Id { get; set; } }
+
+// Source-gen context that only knows about Person
+[JsonSerializable(typeof(Person))]
+public partial class DemoContext : JsonSerializerContext;

